#!/usr/bin/env python
"""Replace the figures of the revised paper (DOCX) with the figures regenerated by the pipeline.

Every figure of the revised DOCX carries the key of the exported figure in the picture description
(`wp:docPr/@descr = "f1deg:<key>"`, for example `f1deg:fig04_tracks_primary`).  The script replaces the
bytes of the embedded image with `<figures>/<key>.png` and adapts the height of the picture to the new
aspect ratio (the width is kept).  Nothing else in the document is touched: the XML is edited as text,
only inside the `<w:drawing>` blocks of the replaced figures.

    python scripts/update_docx_figures.py --docx paper.docx --figures outputs_local/full/figures --out paper_new.docx
    python scripts/update_docx_figures.py --docx paper.docx --list                    # which keys the document contains
    python scripts/update_docx_figures.py --docx paper.docx --figures … --only fig04_tracks_primary fig06_interaction_primary
    python scripts/update_docx_figures.py --docx paper.docx --figures … --drop-notes  # also delete the yellow notes
                                                                                      # "Рисунок із запуску …" of replaced figures

The input file is never modified (`--out` is required for a replacement and must differ from `--docx`).
Only the standard library is used.
"""
from __future__ import annotations

import argparse
import re
import struct
import sys
import zipfile
from pathlib import Path
from typing import Dict, List, Optional, Tuple

DOC = "word/document.xml"
RELS = "word/_rels/document.xml.rels"
PAGE_TEXT_HEIGHT_EMU = int(0.80 * (16840 - 1474 - 964) * 635)   # same limit as the builder of the paper: 80 % of the text height (A4)
NOTE_PREFIX = "Рисунок із запуску"


def png_size(data: bytes) -> Tuple[int, int]:
    if data[:8] != b"\x89PNG\r\n\x1a\n" or data[12:16] != b"IHDR":
        raise ValueError("not a PNG file")
    return struct.unpack(">II", data[16:24])


def find_figures(xml: str) -> List[Dict[str, object]]:
    """All drawings that carry an `f1deg:<key>` description: key, relationship id, span in the XML, extent."""
    out = []
    for m in re.finditer(r"<w:drawing>.*?</w:drawing>", xml, flags=re.S):
        block = m.group(0)
        k = re.search(r'<wp:docPr\b[^>]*\bdescr="f1deg:([^"]+)"', block)
        if not k:
            continue
        rid = re.search(r'<a:blip\b[^>]*\br:embed="([^"]+)"', block)
        ext = re.search(r'<wp:extent\b[^>]*\bcx="(\d+)"[^>]*\bcy="(\d+)"', block)
        out.append({"key": k.group(1), "rid": rid.group(1) if rid else None, "span": m.span(),
                    "cx": int(ext.group(1)) if ext else None, "cy": int(ext.group(2)) if ext else None})
    return out


def rel_targets(rels_xml: str) -> Dict[str, str]:
    out = {}
    for m in re.finditer(r"<Relationship\b[^>]*>", rels_xml):
        tag = m.group(0)
        i = re.search(r'\bId="([^"]+)"', tag); t = re.search(r'\bTarget="([^"]+)"', tag)
        if i and t:
            out[i.group(1)] = t.group(1)
    return out


def set_extent(block: str, cx: int, cy: int) -> str:
    block = re.sub(r'(<wp:extent\b[^>]*\bcx=")\d+("[^>]*\bcy=")\d+(")', rf"\g<1>{cx}\g<2>{cy}\g<3>", block)
    block = re.sub(r'(<a:ext\b[^>]*\bcx=")\d+("[^>]*\bcy=")\d+(")', rf"\g<1>{cx}\g<2>{cy}\g<3>", block)
    return block


def drop_note_after(xml: str, pos: int) -> Tuple[str, int]:
    """Delete the highlighted runs "Рисунок із запуску …" in the caption paragraph that follows position `pos`."""
    nxt = re.compile(r"<w:p\b[^>]*>.*?</w:p>", flags=re.S).search(xml, pos)       # the paragraph after the picture paragraph = caption
    if not nxt:
        return xml, 0
    par = nxt.group(0)
    removed = 0

    def repl(m):
        nonlocal removed
        run = m.group(0)
        if "<w:highlight" in run and NOTE_PREFIX in re.sub(r"<[^>]+>", "", run):
            removed += 1
            return ""
        return run

    new_par = re.sub(r"<w:r\b[^>]*>(?:(?!</w:r>).)*</w:r>", repl, par, flags=re.S)
    if removed:
        xml = xml[: nxt.start()] + new_par + xml[nxt.end():]
    return xml, removed


def main(argv: Optional[List[str]] = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--docx", required=True, help="revised paper (input, not modified)")
    ap.add_argument("--figures", help="directory with the regenerated figures (<key>.png), e.g. outputs_local/full/figures")
    ap.add_argument("--out", help="output DOCX")
    ap.add_argument("--only", nargs="*", help="replace only these keys")
    ap.add_argument("--list", action="store_true", help="list the figure keys of the document and exit")
    ap.add_argument("--drop-notes", action="store_true", help=f'delete the highlighted caption notes "{NOTE_PREFIX} …" of the replaced figures')
    ap.add_argument("--dry-run", action="store_true", help="report what would be replaced, write nothing")
    a = ap.parse_args(argv)

    src = Path(a.docx)
    with zipfile.ZipFile(src) as z:
        names = z.namelist()
        xml = z.read(DOC).decode("utf-8")
        rels = rel_targets(z.read(RELS).decode("utf-8"))
        payload = {n: z.read(n) for n in names}
        infos = {n: z.getinfo(n) for n in names}
    figs = find_figures(xml)
    if a.list or not a.figures:
        print(f"{src.name}: {len(figs)} figure(s) with an f1deg key")
        for f in figs:
            print(f"  {f['key']:<40s} {rels.get(f['rid'], '?'):<48s} {f['cx']}×{f['cy']} EMU")
        if not a.list:
            print("nothing replaced: --figures not given")
        return 0
    if not a.out and not a.dry_run:
        ap.error("--out is required (the input file is never modified)")
    if a.out and Path(a.out).resolve() == src.resolve():
        ap.error("--out must differ from --docx")

    fig_dir = Path(a.figures)
    replaced, missing, notes = [], [], 0
    for f in sorted(figs, key=lambda d: d["span"][0], reverse=True):      # back to front: spans stay valid
        key = f["key"]
        if a.only and key not in a.only:
            continue
        png = fig_dir / f"{key}.png"
        if not png.exists():
            missing.append(key)
            continue
        target = rels.get(f["rid"])
        if target is None:
            print(f"!! {key}: relationship {f['rid']} not found, skipped", file=sys.stderr)
            continue
        data = png.read_bytes()
        w, h = png_size(data)
        cx = int(f["cx"]); cy = int(round(cx * h / w))
        if cy > PAGE_TEXT_HEIGHT_EMU:
            cx = int(cx * PAGE_TEXT_HEIGHT_EMU / cy); cy = PAGE_TEXT_HEIGHT_EMU
        s, e = f["span"]
        xml = xml[:s] + set_extent(xml[s:e], cx, cy) + xml[e:]
        if a.drop_notes:
            end_of_par = xml.find("</w:p>", s)
            xml, k = drop_note_after(xml, end_of_par + len("</w:p>"))
            notes += k
        payload["word/" + target.lstrip("/")] = data
        replaced.append((key, f"{w}×{h} px", f"{f['cx']}×{f['cy']} → {cx}×{cy} EMU"))

    for r in sorted(replaced):
        print("replaced:", *r)
    for k in sorted(missing):
        print(f"kept (no {k}.png in {fig_dir}):", k)
    if a.drop_notes:
        print(f"caption notes removed: {notes}")
    if a.dry_run:
        print("dry run: nothing written")
        return 0
    payload[DOC] = xml.encode("utf-8")
    out = Path(a.out)
    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
        for n in names:                                                    # original order ([Content_Types].xml first)
            if n.endswith("/"):
                continue                                                   # no directory entries
            zi = zipfile.ZipInfo(n, date_time=infos[n].date_time)
            zi.compress_type = zipfile.ZIP_DEFLATED
            zi.external_attr = infos[n].external_attr
            z.writestr(zi, payload[n])
    print(f"written: {out}  ({len(replaced)} figure(s) replaced, {len(missing)} kept)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
